-- LInsight universal model families and large reusable algorithm catalog.
-- Preconditions: V202609022300 has completed.
-- Data/lock impact: adds three algorithm metadata columns, 17 logical PRESET model assets,
--   223 algorithm templates and the same number of immutable Pipeline v1 rows.
-- No model binary, license approval, SHA256 or acceptance evidence is fabricated.
-- Forward repair: resolve conflicting fixed ids/codes and apply a new migration; never edit this file after registration.
-- Rollback before references exist: delete pipeline ids 82200..82422, delete algorithm ids 72200..72422,
--   delete model ids 71013..71029, then drop the added index and columns.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE ai_algorithm
  ADD COLUMN scene_group varchar(64) NOT NULL DEFAULT 'GENERAL' COMMENT '算法场景分组' AFTER category,
  ADD COLUMN implementation_type varchar(32) NOT NULL DEFAULT 'MODEL_DIRECT' COMMENT 'MODEL_DIRECT/MODEL_FILTER/TRACK_RULE/CLASSICAL_CV/COMPOSITE' AFTER scene_group,
  ADD COLUMN required_capabilities json NULL COMMENT '运行依赖的受控能力键' AFTER capability_key,
  ADD KEY idx_ai_algorithm_tenant_scene_status (tenant_id, scene_group, status);

UPDATE ai_algorithm
SET scene_group = CASE
  WHEN code IN ('safety-helmet','reflective-vest') THEN 'PPE'
  WHEN code IN ('smoking-detection','phone-call-detection') THEN 'SMOKING_PHONE'
  WHEN code IN ('person-intrusion','area-intrusion','person-absence','person-detection-base') THEN 'PERSON'
  WHEN code = 'fall-detection' THEN 'FALL'
  WHEN code = 'flame-detection' THEN 'FIRE_SMOKE'
  WHEN code = 'vehicle-detection' THEN 'VEHICLE'
  WHEN code = 'license-plate' THEN 'LICENSE_PLATE'
  ELSE 'GENERAL'
END,
implementation_type = CASE
  WHEN code IN ('person-intrusion','area-intrusion','person-absence') THEN 'TRACK_RULE'
  WHEN code IN ('safety-helmet','reflective-vest','smoking-detection','phone-call-detection','fall-detection') THEN 'COMPOSITE'
  ELSE 'MODEL_DIRECT'
END,
required_capabilities = JSON_ARRAY(capability_key);

